{"content":"import 'package:mad_flutter_practicum/app/currency_list/widgets/currency_card.dart';
import 'package:mad_flutter_practicum/app/news_list/widgets/news_card.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

class DashboardPage extends StatefulWidget {
  const DashboardPage({super.key});

  @override
  State<DashboardPage> createState() => _DashboardPageState();
}

class _DashboardPageState extends State<DashboardPage> {
  late Future<void> _dataFuture;

  CurrencyPage? _currencyPage;
  List<NewsModel>? _newsList;

  @override
  void initState() {
    super.initState();
    _loadData();
  }

  /// Загружает курс валют и ленту новостей параллельно.
  Future<void> _loadData() async {
    final currencyRepository = context.read<CurrencyRepository>();
    final newsRepository = context.read<NewsRepository>();

    try {
      final results = await Future.wait([
        currencyRepository.fetchRates(const CurrencyPageRequest()),
        newsRepository.loadNewsFeed(const NewsFeedFilter()),
      ]);

      if (!mounted) return;

      setState(() {
        _currencyPage = results[0] as CurrencyPage;
        _newsList = results[1] as List<NewsModel>;
        _dataFuture = Future.value(); // данные успешно загружены, индикатор скрываем
      });
    } catch (_) {
      if (!mounted) return;

      setState(() {
        _currencyPage ??= const CurrencyPage(items: [], page: 0, hasMore: false);
        _newsList = [];
        _dataFuture = Future.value();
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    final AppLocalizations loc = context.loc;

    return Scaffold(
      appBar: AppBar(title: Text(loc.dashboard)),
      body: FutureBuilder<void>(
        future: _dataFuture,
        builder: (BuildContext context, AsyncSnapshot<void> snapshot) {
          // Данные ещё не загружены — показываем прогресс-индикатор
          if (_currencyPage == null && _newsList == null) {
            return const Padding(
              padding: EdgeInsets.only(top: 24),
              child: LinearProgressIndicator(),
            );
          }

          final List<CurrencyModel> currencies = _currencyPage!.items;
          final List<NewsModel> news = _newsList ?? [];

          return ListView(
            padding: const EdgeInsets.fromLTRB(20, 8, 20, 40),
            children: [
              // --- Блок курса валют ---
              if (currencies.isNotEmpty) ...[
                Text(
                  loc.currencyRate,
                  style: context.fonts.regular16,
                ),
                const SizedBox(height: 8),
                ...List.generate(currencies.length, (int index) {
                  final CurrencyModel currency = currencies[index];
                  return Padding(
                    key: ValueKey(currency.id),
                    padding: const EdgeInsets.only(bottom: 6),
                    child: CurrencyCard(model: currency),
                  );
                }),
              ],

              // --- Блок новостей ---
              if (news.isNotEmpty) ...[
                const SizedBox(height: 18),
                Text(
                  loc.news,
                  style: context.fonts.regular16,
                ),
                const SizedBox(height: 8),
                ...List.generate(news.length, (int index) {
                  final NewsModel item = news[index];
                  return Padding(
                    key: ValueKey(item.link),
                    padding: const EdgeInsets.only(bottom: 10),
                    child: NewsCard(model: item),
                  );
                }),
              ],

              // --- Пустое состояние, если ничего не загрузилось ---
              if (currencies.isEmpty && news.isEmpty)
                Center(
                  child: Text(
                    loc.noData,
                    style: context.fonts.regular14,
                  ),
                ),
            ],
          );
        },
      ),
    );
  }
}
